package com.shopsphere;
import jakarta.persistence.*;import java.time.Instant;import java.util.*;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.stereotype.Repository;
@Entity @Table(name="users") class UserEntity{@Id UUID id;String firstName;String lastName;@Column(nullable=false,unique=true)String email;String passwordHash;String phone;@Enumerated(EnumType.STRING)User.Role role;boolean enabled;Instant createdAt;Instant updatedAt;protected UserEntity(){}UserEntity(User u){id=u.id();firstName=u.firstName();lastName=u.lastName();email=u.email();passwordHash=u.passwordHash();phone=u.phone();role=u.role();enabled=u.enabled();createdAt=u.createdAt();updatedAt=u.updatedAt();}User domain(){return new User(id,firstName,lastName,email,passwordHash,phone,role,enabled,createdAt,updatedAt);}}
interface SpringUserRepository extends JpaRepository<UserEntity,UUID>{Optional<UserEntity>findByEmailIgnoreCase(String email);}
@Repository class JpaUserRepository implements UserRepository{private final SpringUserRepository data;JpaUserRepository(SpringUserRepository d){data=d;}public Optional<User>findByEmail(String e){return data.findByEmailIgnoreCase(e).map(UserEntity::domain);}public Optional<User>findById(UUID id){return data.findById(id).map(UserEntity::domain);}public User save(User u){return data.save(new UserEntity(u)).domain();}}
